Date leap = Date.newInstance(2024, 2, 29);
System.assertEquals(60, leap.dayOfYear());
System.assertEquals('2/29/2024', leap.format());
System.assert(Date.isLeapYear(2024));
System.assertEquals(29, Date.daysInMonth(2024, 2));
System.assert(leap.isSameDay(Date.newInstance(2024, 2, 29)));
System.assertEquals(1, Date.newInstance(2024, 1, 29).monthsBetween(leap));
System.assertEquals(Date.newInstance(2024, 2, 25), leap.toStartOfWeek());
System.assertEquals(Date.newInstance(2024, 2, 29), Date.parse('2/29/2024'));
Object dateObject = '2024-02-29';
System.assertEquals(Date.newInstance(2024, 2, 29), Date.valueOf(dateObject));

